// Connect the motor shield to the Arduino
// Connect the left motor to the left motor shield output
// Connect the right motor to the right motor shield output
// Set the speed of the motors
int leftSpeed = 80;
int rightSpeed = 80;
// Set the duty cycle of the motors
analogWrite(leftMotor, leftSpeed);
analogWrite(rightMotor, rightSpeed);
